{
  "IP": "neorv32_sysinfo",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Runtime clock-frequency information",
      "Unit": "neorv32_sysinfo",
      "Information": "The 32-bit clock-frequency value reported by the system-information register is initialized from CLOCK_FREQUENCY and can be replaced by a bus write; software depends on it for the system-information read-back.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is not required by the RTL's use because the value is ordinary system information returned on bus_rsp_o.data at line 168. Integrity is at risk because an unchecked bus write selected by the conditions at line 94 stores bus_req_i.data into sysinfo(0) at line 95. Availability is not implicated because the value does not gate or block any required transfer; the response logic only reads it at line 168. No privileged, override, bypass or test behavior acts on this value; only the normal bus-write condition at line 94 controls modification.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An unauthorized bus write to the clock-frequency register can replace the reported value and cause software relying on system information to use incorrect timing.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        95
      ],
      "Held Lines": [
        92,
        95
      ],
      "Exit Lines": [
        168
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Static hardware capability and configuration metadata",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The build-time-values rule bars this information as a conceptual asset because sysinfo(1) through sysinfo(3) are generated solely from generics and constants and cannot be changed at run time, despite being returned at lines 102-150 and 168."
    },
    {
      "Candidate Name": "Bus access control and buffering",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "Access-command fields are part of the access they perform, while buf_ack only repeats the request strobe and buf_adr only holds the access address during service, as shown at lines 160-162 and 168-170, so they are not information pieces of their own."
    }
  ],
  "Notes": []
}
